class InstallerBoundaries(unittest.TestCase):
    def setUp(self) -> None:
        self.temporary = tempfile.TemporaryDirectory(prefix="godseye-hermes-installer-")
        self.root = Path(self.temporary.name).resolve()
        self.target = self.root / "source"

    def tearDown(self) -> None:
        self.temporary.cleanup()

    def archive(self, entries: list[tuple[str, bytes | str]]) -> Path:
        path = self.root / "fixture.tar.gz"
        with tarfile.open(path, "w:gz") as package:
            for name, content in entries:
                info = tarfile.TarInfo(name)
                if isinstance(content, str):
                    info.type = tarfile.SYMTYPE
                    info.linkname = content
                    package.addfile(info)
                else:
                    info.size = len(content)
                    package.addfile(info, io.BytesIO(content))
        return path

    def test_changed_cached_archive_is_refused_before_network(self) -> None:
        path = self.root / "archive.tar.gz"
        path.write_bytes(b"fixture changed download")
        with patch.object(FILES.urllib.request, "urlopen", side_effect=AssertionError("network called")):
            with self.assertRaisesRegex(RuntimeError, "reviewed hash"):
                FILES.download("https://example.test/unused", path, "0" * 64)
        self.assertEqual(path.read_bytes(), b"fixture changed download")

    def test_matching_cached_archive_is_used_without_network(self) -> None:
        path = self.root / "archive.tar.gz"
        content = b"fixture reviewed download"
        path.write_bytes(content)
        with patch.object(FILES.urllib.request, "urlopen", side_effect=AssertionError("network called")):
            FILES.download("https://example.test/unused", path, hashlib.sha256(content).hexdigest())
        self.assertEqual(path.read_bytes(), content)

    def test_archive_traversal_is_refused_without_outside_write(self) -> None:
        archive = self.archive([("fixture/../escaped.txt", b"outside")])
        with self.assertRaises(RuntimeError):
            FILES.extract(archive, self.target, "fixture", False)
        self.assertFalse(self.target.exists())
        self.assertFalse((self.root / "escaped.txt").exists())
        self.assertEqual(sorted(item.name for item in self.root.iterdir()), ["fixture.tar.gz"])

    def test_archive_absolute_path_is_refused(self) -> None:
        archive = self.archive([("/fixture/escaped.txt", b"outside")])
        with self.assertRaises(RuntimeError):
            FILES.extract(archive, self.target, "fixture", False)
        self.assertFalse(self.target.exists())

    def test_source_archive_links_are_refused(self) -> None:
        archive = self.archive([("fixture/alias", "../outside")])
        with self.assertRaises(RuntimeError):
            FILES.extract(archive, self.target, "fixture", False)
        self.assertFalse(self.target.exists())

    def test_runtime_archive_link_cannot_escape_its_stage(self) -> None:
        archive = self.archive([("fixture/alias", "../../outside")])
        with self.assertRaises(RuntimeError):
            FILES.extract(archive, self.target, "fixture", True)
        self.assertFalse(self.target.exists())

    def test_archive_extraction_cannot_replace_existing_installation(self) -> None:
        self.target.mkdir(mode=0o700)
        sentinel = self.target / "retained.txt"
        sentinel.write_bytes(b"retained installation")
        archive = self.archive([("fixture/new.txt", b"new")])
        with self.assertRaises(RuntimeError):
            FILES.extract(archive, self.target, "fixture", False)
        self.assertEqual(sentinel.read_bytes(), b"retained installation")
        self.assertFalse((self.target / "new.txt").exists())

    def test_archive_entry_bound_is_enforced_before_publish(self) -> None:
        archive = self.archive([("fixture/a", b"a"), ("fixture/b", b"b")])
        with patch.object(FILES, "MAX_ARCHIVE_ENTRIES", 1):
            with self.assertRaises(RuntimeError):
                FILES.extract(archive, self.target, "fixture", False)
        self.assertFalse(self.target.exists())

    def test_immutable_tree_refuses_an_escaping_link(self) -> None:
        self.target.mkdir(mode=0o700)
        (self.target / "alias").symlink_to(self.root / "outside")
        with self.assertRaises(RuntimeError):
            FILES.tree_hashes(self.target, self.target)

    def test_immutable_tree_refuses_a_multiply_linked_file(self) -> None:
        self.target.mkdir(mode=0o700)
        original = self.target / "file.txt"
        original.write_bytes(b"fixture")
        os.link(original, self.root / "alias.txt")
        with self.assertRaises(RuntimeError):
            FILES.tree_hashes(self.target, self.target)

    def test_bootstrap_environment_excludes_parent_authority_and_preloads(self) -> None:
        with patch.dict(os.environ, {
            "OPENAI_API_KEY": "fixture-not-a-key",
            "GODSEYE_DATABASE_URL": "fixture-owner-database",
            "HERMES_HOME": "/fixture-account-hermes",
            "PYTHONPATH": "/fixture-injected-python",
            "PYTHONSTARTUP": "/fixture-injected-startup",
            "LD_PRELOAD": "/fixture-injected-library",
            "NODE_OPTIONS": "fixture-injected-node",
        }):
            environment = INSTALLER.child_environment(self.root)
        self.assertFalse(any("fixture-" in value for value in environment.values()))
        self.assertTrue(Path(environment["HOME"]).is_relative_to(self.root))
        self.assertTrue(Path(environment["HERMES_HOME"]).is_relative_to(self.root))
        self.assertEqual(environment["PYTHONNOUSERSITE"], "1")

    def test_different_release_provenance_is_refused_without_adoption(self) -> None:
        receipt = self.root / "provenance.json"
        FILES.write_json(receipt, {"version": "fixture-other-release"})
        before = receipt.read_bytes()
        with self.assertRaisesRegex(RuntimeError, "provenance differs"):
            INSTALLER.verify_install(self.root)
        self.assertEqual(receipt.read_bytes(), before)

    def test_modified_completed_source_is_refused_without_replacement(self) -> None:
        for name in ("source", "python", "venv", "identity"):
            path = self.root / name
            path.mkdir(mode=0o700)
            (path / "fixture.txt").write_bytes(b"original")
        FILES.write_json(self.root / "provenance.json", {
            "version": INSTALLER.VERSION, "commit": INSTALLER.COMMIT,
            "sourceSha256": INSTALLER.SOURCE_SHA256, "pythonSha256": INSTALLER.PYTHON_SHA256,
        })
        FILES.write_json(self.root / "immutable-files.json", INSTALLER.immutable_files(self.root))
        source = self.root / "source/fixture.txt"
        source.write_bytes(b"modified")
        with self.assertRaisesRegex(RuntimeError, "runtime bytes differ"):
            INSTALLER.verify_install(self.root)
        self.assertEqual(source.read_bytes(), b"modified")

    def test_changed_original_extraction_bytes_are_refused_without_quarantine(self) -> None:
        target, reference = self.root / "source", self.root / "reference"
        for directory in (target, reference):
            directory.mkdir(mode=0o700)
            (directory / "module.py").write_bytes(b"original")
        (target / "module.py").write_bytes(b"modified")
        with self.assertRaisesRegex(RuntimeError, "differs"):
            INSTALLER.verify_extraction(target, reference, self.root, "source")
        self.assertEqual((target / "module.py").read_bytes(), b"modified")
        self.assertFalse(any(self.root.glob("interrupted-*")))

    def test_unknown_extraction_addition_is_refused_without_adoption(self) -> None:
        target, reference = self.root / "source", self.root / "reference"
        for directory in (target, reference):
            directory.mkdir(mode=0o700)
            (directory / "module.py").write_bytes(b"original")
        (target / "unexpected.py").write_bytes(b"unreviewed")
        with self.assertRaisesRegex(RuntimeError, "unrecognized"):
            INSTALLER.verify_extraction(target, reference, self.root, "source")
        self.assertTrue((target / "unexpected.py").is_file())

    def test_known_derived_metadata_is_retained_before_clean_retry_publication(self) -> None:
        target, reference = self.root / "source", self.root / "reference"
        for directory in (target, reference):
            directory.mkdir(mode=0o700)
            (directory / "module.py").write_bytes(b"original")
        metadata = target / "hermes_agent.egg-info"
        metadata.mkdir(mode=0o700)
        (metadata / "PKG-INFO").write_bytes(b"derived fixture metadata")
        INSTALLER.verify_extraction(target, reference, self.root, "source")
        retained = list(self.root.glob("interrupted-source-*"))
        self.assertEqual(len(retained), 1)
        self.assertEqual((retained[0] / "hermes_agent.egg-info/PKG-INFO").read_bytes(), b"derived fixture metadata")
        self.assertFalse((target / "hermes_agent.egg-info").exists())
        self.assertEqual((target / "module.py").read_bytes(), b"original")

    def test_build_hardlink_detachment_preserves_cache_bytes_and_changes_inode(self) -> None:
        cache = self.root / "cache.txt"
        cache.write_bytes(b"fixture cached wheel bytes")
        target = self.root / "venv"
        target.mkdir(mode=0o700)
        linked = target / "module.py"
        os.link(cache, linked)
        old_inode = cache.stat().st_ino
        FILES.detach_build_hardlinks(target)
        self.assertEqual(cache.read_bytes(), b"fixture cached wheel bytes")
        self.assertEqual(linked.read_bytes(), cache.read_bytes())
        self.assertEqual(cache.stat().st_ino, old_inode)
        self.assertNotEqual(linked.stat().st_ino, old_inode)
        self.assertEqual(linked.stat().st_nlink, 1)

    def test_build_hardlink_detachment_refuses_a_linked_root(self) -> None:
        actual = self.root / "actual"
        actual.mkdir(mode=0o700)
        linked = self.root / "venv"
        linked.symlink_to(actual, target_is_directory=True)
        with self.assertRaises(RuntimeError):
            FILES.detach_build_hardlinks(linked)

    def test_immutable_tree_refuses_a_linked_root(self) -> None:
        actual = self.root / "actual"
        actual.mkdir(mode=0o700)
        linked = self.root / "source"
        linked.symlink_to(actual, target_is_directory=True)
        with self.assertRaises(RuntimeError):
            FILES.tree_hashes(linked, self.root)


